/bin/zsh -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { sanitizeBody, INTERNAL_EFFORT_FIELD } from './target.mjs';
const dictionaries = [
  { type: 'object', additionalProperties: true },
  { type: 'object', properties: {}, additionalProperties: { type: 'string' } },
  { type: 'object', properties: {}, patternProperties: { '"'^x'"': { type: 'number' } } },
  { type: 'object', additionalProperties: false, patternProperties: { '"'^x'"': { type: 'string' } } },
];
for (const dictionary of dictionaries) {
  for (const wrap of [d => d, d => ({ type: 'object', properties: { data: d } }), d => ({ type: 'array', items: d }), ...['anyOf', 'oneOf', 'allOf'].map(key => d => ({ type: 'object', [key]: [d] })), d => ({ type: 'array', items: [d] })]) {
    const schema = wrap(structuredClone(dictionary));
    const before = structuredClone(schema);
    sanitizeBody({ tools: [{ input_schema: schema }] });
    // Alternative containers retain legacy normalization; the dictionary itself stays unchanged.
    const inner = schema.anyOf?.[0] || schema.oneOf?.[0] || schema.allOf?.[0] || schema.properties?.data || (Array.isArray(schema.items) ? schema.items[0] : schema.items) || schema;
    assert.deepEqual(inner, dictionary);
  }
}
const named = { type: 'object', properties: { name: { type: 'string' } }, required: ['name'], additionalProperties: false };
assert.deepEqual(sanitizeBody({ tools: [{ input_schema: structuredClone(named) }] }).tools[0].input_schema, named);
const closed = sanitizeBody({ tools: [{ input_schema: { type: 'object', properties: {}, additionalProperties: false } }] }).tools[0].input_schema;
assert.equal(closed.additionalProperties, false);
assert.deepEqual(sanitizeBody({ tools: [{}] }).tools[0].input_schema, { type: 'object', properties: {}, additionalProperties: false });
const body = sanitizeBody({ betas: [], metadata: {}, max_tokens: 1, output_config: { effort: 'high' }, tool_choice: 'auto', tools: [{ strict: true }] });
assert.equal(body.max_tokens, 16);
assert.equal(body[INTERNAL_EFFORT_FIELD], 'high');
assert.equal(Object.keys(body).includes(INTERNAL_EFFORT_FIELD), false);
assert.deepEqual(body.tool_choice, { type: 'auto' });
assert.equal('strict' in body.tools[0], false);
console.log('Dictionary, nesting, closed-object, named-property, and unrelated behavior checks passed.');
JS"
